public class Solution
{
    public int LongestConsecutive(int[] nums)
    {
        var seen = nums.ToHashSet();
        int best = 0;
        foreach (int v in seen)
            if (!seen.Contains(v - 1))
            {
                int end = v;
                while (seen.Contains(end))
                    end++;
                best = Math.Max(best, end - v);
            }
        return best;
    }
}

