public class Solution {
  public boolean canAttendMeetings(int[][] intervals) {
    int[][] rows = intervals.clone();
    Arrays.sort(rows, Comparator.comparingInt(r -> r[0]));
    for (int i = 1; i < rows.length; i++)
      if (rows[i][0] < rows[i - 1][1])
        return false;
    return true;
  }
}

