class Solution {
 public:
  int MinMeetingRooms(std::vector<std::vector<int>>& intervals) {
    std::vector<std::pair<int, int>> events;
    for (auto row : intervals) {
      events.emplace_back(row[0], 1);
      events.emplace_back(row[1], -1);
    }
    std::sort(events.begin(), events.end());
    int active = 0, best = 0;
    for (auto e : events) {
      active += e.second;
      best = std::max(best, active);
    }
    return best;
  }
};

