  std::vector<std::string> Decode(std::string encoded) {
    std::vector<std::string> out;
    size_t i = 0;
    while (i < encoded.size()) {
      auto j = encoded.find(':', i);
      auto n = std::stoul(encoded.substr(i, j - i));
      i = j + 1;
      out.push_back(encoded.substr(i, n));
      i += n;
    }
    return out;
  }
};

