function minWindow(s, t) {
  const need = Array(128).fill(0);
  for (const c of t) need[c.charCodeAt(0)]++;
  let missing = t.length,
    left = 0,
    start = 0,
    length = Infinity;
  for (let r = 0; r < s.length; r++) {
    if (need[s.charCodeAt(r)]-- > 0) missing--;
    while (missing === 0) {
      if (r - left + 1 < length) {
        start = left;
        length = r - left + 1;
      }
      if (++need[s.charCodeAt(left++)] > 0) missing++;
    }
  }
  return length === Infinity ? "" : s.slice(start, start + length);
}

