def min_window(s: str, t: str) -> str:
    need = Counter(t)
    missing = len(t)
    left = start = 0
    length = len(s) + 1
    for r, c in enumerate(s):
        if need[c] > 0:
            missing -= 1
        need[c] -= 1
        while missing == 0:
            if r - left + 1 < length:
                start = left
                length = r - left + 1
            need[s[left]] += 1
            if need[s[left]] > 0:
                missing += 1
            left += 1
    return "" if length > len(s) else s[start : start + length]

