{
    public void SetZeroes(int[][] matrix)
    {
        int rows = matrix.Length, cols = matrix[0].Length;
        var zeroRows = new bool[rows];
        var zeroCols = new bool[cols];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
