  ListNode* MergeTwoLists(ListNode* list1, ListNode* list2) {
    auto a = ListAlgorithms::nodes(list1);
    auto b = ListAlgorithms::nodes(list2);
    a.insert(a.end(), b.begin(), b.end());
    std::stable_sort(a.begin(), a.end(), [](auto x, auto y) { return x->val < y->val; });

    return ListAlgorithms::link(a);
  }
};

