    List<ListNode> a = new ArrayList<>();
    for (ListNode h : lists)
      a.addAll(ListAlgorithms.nodes(h));
    a.sort(Comparator.comparingInt(n -> n.val));

    return ListAlgorithms.link(a);
  }
}

class ListAlgorithms {
  static List<ListNode> nodes(ListNode n) {
    List<ListNode> a = new ArrayList<>();
    while (n != null) {
      a.add(n);
      n = n.next;
    }
    return a;
  }

  static ListNode link(List<ListNode> a) {
    for (int i = 0; i < a.size(); i++)
      a.get(i).next = i + 1 < a.size() ? a.get(i + 1) : null;
    return a.isEmpty() ? null : a.get(0);
  }
}

