TreeNode* read(std::istringstream& in) {
  std::string s;
  in >> s;
  if (s == "#")
    return nullptr;
  auto n = new TreeNode(std::stoi(s));
  n->left = read(in);
  n->right = read(in);
  return n;
}

TreeNode* deserialize(const std::string& s) {
  std::istringstream in(s);
  return read(in);
}
