class Solution {
 public:
  bool IsValidBST(TreeNode* root) {
    auto a = TreeAlgorithms::inorder(root);
    for (size_t i = 1; i < a.size(); i++)
      if (a[i - 1] >= a[i])
        return false;
    return true;
  }
};

