public class Solution
{
    public string[] FindWords(string[] board, string[] words)
    {
        var outp = new List<string>();
        foreach (string word in words.Distinct())
        {
            int rows = board.Length, cols = board[0].Length;
            var used = Enumerable.Range(0, rows)
                           .Select(
                               _ => new bool[cols])
                           .ToArray();
            bool Visit(int r, int c, int i)
            {
                if (r < 0 || r >= rows || c < 0 || c >= cols || used[r][c] ||
                    board[r][c] != word[i])
                    return false;
                if (i == word.Length - 1)
                    return true;
                used[r][c] = true;
                bool ok = Visit(r - 1, c, i + 1) || Visit(r + 1, c, i + 1) ||
                          Visit(r, c - 1, i + 1) || Visit(r, c + 1, i + 1);
                used[r][c] = false;
                return ok;
            }
            bool found = false;
            for (int r = 0; r < rows && !found; r++)
                for (int c = 0; c < cols && !found; c++)
                    found = Visit(r, c, 0);
            if (found)
                outp.Add(word);
        }
        return outp.ToArray();
    }
}

