{
    public int NumDecodings(string s)
    {
        System.Numerics.BigInteger a = 1, b = s[0] == '0' ? 0 : 1;
        for (int i = 1; i < s.Length; i++)
        {
            System.Numerics.BigInteger next = s[i] == '0' ? 0 : b;
            int pair = (s[i - 1] - '0') * 10 + s[i] - '0';
            if (pair >= 10 && pair <= 26)
                next += a;
            a = b;
            b = next;
        }
        return (int)b;
    }
}

