public class Solution {
  public int combinationSum4(int[] nums, int target) {
    java.math.BigInteger[] dp = new java.math.BigInteger[target + 1];
    Arrays.fill(dp, java.math.BigInteger.ZERO);
    dp[0] = java.math.BigInteger.ONE;
    for (int v = 1; v <= target; v++)
      for (int c : nums)
        if (c <= v)
          dp[v] = dp[v].add(dp[v - c]);
    return dp[target].intValueExact();
  }
}

