public class Solution
{
    public int GetMaxProfit(int[] prices)
    {
        if (prices.Length < 2)
            throw new ArgumentException();
        int minimum = prices[0], best = prices[1] - prices[0];
        for (int i = 1; i < prices.Length; i++)
