class Solution {
  public boolean IsValid(String code) {
    var open = new ArrayDeque<Character>();
    for (char c : code.toCharArray()) {
      if (c == '(' || c == '[' || c == '{')
        open.push(c);
      else if (c == ')' || c == ']' || c == '}') {
        if (open.isEmpty())
          return false;
        char left = open.pop();
        if ((c == ')' && left != '(') || (c == ']' && left != '[') || (c == '}' && left != '{'))
          return false;
      }
    }
    return open.isEmpty();
  }
}

