entries.solutionCode:
class Solution:
    def IsFirstComeFirstServed(
        self, takeOut: list[int], dineIn: list[int], served: list[int]
    ) -> bool:
        if len(served) != len(takeOut) + len(dineIn):
            return False
        take_index = dine_index = 0
        for order in served:
            if take_index < len(takeOut) and order == takeOut[take_index]:
                take_index += 1
            elif dine_index < len(dineIn) and order == dineIn[dine_index]:
                dine_index += 1
            else:
                return False
        return take_index == len(takeOut) and dine_index == len(dineIn)

