class Solution {
  public boolean IsFirstComeFirstServed(int[] takeOut, int[] dineIn, int[] served) {
    if (served.length != takeOut.length + dineIn.length)
      return false;
    int take = 0, dine = 0;
    for (int order : served) {
      if (take < takeOut.length && takeOut[take] == order)
        take++;
      else if (dine < dineIn.length && dineIn[dine] == order)
        dine++;
      else
        return false;
    }
    return take == takeOut.length && dine == dineIn.length;
  }
}

