class Solution {
 public:
  int Fib(int n) {
    if (n < 2)
      return n;
    int previous = 0, current = 1;
    for (int i = 2; i <= n; ++i) {
      int next = previous + current;
      previous = current;
      current = next;
    }
    return current;
  }
};

