class Solution:
    def FindDuplicateFiles(self, startingDirectory: str) -> list[FilePaths]:
        seen = {}
        duplicates = []
        for path in Path(startingDirectory).rglob("*"):
            if not path.is_file():
                continue
            full_path = str(path.resolve())
            metadata = path.stat()
            last = max(0, metadata.st_size - 64)
            with path.open("rb") as stream:
                samples = []
                for offset in (0, last // 2, last):
                    stream.seek(offset)
                    samples.append(stream.read(64))
            fingerprint = (metadata.st_size, tuple(samples))
            if fingerprint in seen:
                previous, earlier_time = seen[fingerprint]
                if earlier_time <= metadata.st_mtime_ns:
                    duplicates.append(FilePaths(previous, full_path))
                else:
                    duplicates.append(FilePaths(full_path, previous))
            else:
                seen[fingerprint] = (full_path, metadata.st_mtime_ns)
        return duplicates

