public class Solution
{
    public int FindRepeat(int[] numbers)
    {
        int lower = 1, upper = numbers.Length - 1;
        while (lower < upper)
        {
            int middle = lower + (upper - lower) / 2, count = 0;
            foreach (int value in numbers)
                if (value >= lower && value <= middle)
                    count++;
            if (count > middle - lower + 1)
                upper = middle;
            else
                lower = middle + 1;
        }
        return lower;
    }
}

