            int x = values[i];
            best = Math.Max(best, Math.Max(x * highTwo, x * lowTwo));
            highTwo = Math.Max(highTwo, Math.Max(x * high, x * low));
            lowTwo = Math.Min(lowTwo, Math.Min(x * high, x * low));
            high = Math.Max(high, x);
            low = Math.Min(low, x);
        }
        return best;
    }
}

