class QueueTwoStacks {
  private final Stack<Integer> incoming = new Stack<>(), outgoing = new Stack<>();
  public void Enqueue(int item) {
    incoming.push(item);
  }
  public int Dequeue() {
    if (outgoing.empty())
      while (!incoming.empty())
        outgoing.push(incoming.pop());
    if (outgoing.empty())
      throw new NoSuchElementException();
    return outgoing.pop();
  }
}

