public class Solution
{
    public bool CanTwoMoviesFillFlight(int[] movieLengths, int flightLength)
    {
        var earlier = new HashSet<int>();
        foreach (int length in movieLengths)
        {
            if (earlier.Contains(flightLength - length))
                return true;
            earlier.Add(length);
        }
        return false;
    }
}

