class Solution {
 public:
  vector<Meeting*> MergeRanges(vector<Meeting*>& meetings) {
    vector<Meeting*> ordered = meetings;
    sort(ordered.begin(), ordered.end(),
         [](Meeting* a, Meeting* b) { return a->StartTime < b->StartTime; });
    vector<Meeting*> merged;
    for (auto meeting : ordered) {
      if (merged.empty() || meeting->StartTime > merged.back()->EndTime)
        merged.push_back(new Meeting(meeting->StartTime, meeting->EndTime));
      else
        merged.back()->EndTime = max(merged.back()->EndTime, meeting->EndTime);
    }
    return merged;
  }
