  vector<string> BfsGetPath(unordered_map<string, vector<string>>& graph, const string& start,
                            const string& end) {
    queue<string> pending;
    unordered_map<string, string> predecessor;
    predecessor[start] = start;
    pending.push(start);
    while (!pending.empty()) {
      string vertex = pending.front();
      pending.pop();
      if (vertex == end) {
        vector<string> path;
        for (string at = end;; at = predecessor.at(at)) {
          path.push_back(at);
          if (at == start)
            break;
        }
        reverse(path.begin(), path.end());
        return path;
      }
      for (const auto& neighbor : graph.at(vertex)) {
        if (!predecessor.count(neighbor)) {
          predecessor[neighbor] = vertex;
          pending.push(neighbor);
        }
      }
    }
    return {};
  }
};

