class Solution {
  public String[] BfsGetPath(Map<String, String[]> graph, String start, String end) {
    var parent = new HashMap<String, String>();
    var queue = new ArrayDeque<String>();
    parent.put(start, null);
    queue.add(start);
    while (!queue.isEmpty()) {
      String current = queue.remove();
      if (current.equals(end))
        break;
      for (String neighbor : graph.get(current))
        if (!parent.containsKey(neighbor)) {
          parent.put(neighbor, current);
          queue.add(neighbor);
        }
    }
    if (!parent.containsKey(end))
      return null;
    var route = new ArrayList<String>();
    for (String current = end; current != null; current = parent.get(current))
      route.add(current);
    Collections.reverse(route);
    return route.toArray(String[] ::new);
  }
}

