{
    public int[] GetProductsOfAllIntsExceptAtIndex(int[] values)
    {
        if (values.Length < 2)
            throw new ArgumentException();
        var result = new int[values.Length];
        int prefix = 1;
        for (int i = 0; i < values.Length; i++)
        {
            result[i] = prefix;
            prefix *= values[i];
        }
        int suffix = 1;
        for (int i = values.Length - 1; i >= 0; i--)
        {
            result[i] *= suffix;
            suffix *= values[i];
        }
        return result;
    }
}

