class Solution {
  public int[] GetProductsOfAllIntsExceptAtIndex(int[] values) {
    int[] result = new int[values.length];
    int product = 1;
    for (int i = 0; i < values.length; i++) {
      result[i] = product;
      product *= values[i];
    }
    product = 1;
    for (int i = values.length - 1; i >= 0; i--) {
      result[i] *= product;
      product *= values[i];
    }
    return result;
  }
}

