public class Solution
{
    public Rectangle FindRectangularOverlap(Rectangle first, Rectangle second)
    {
        int left = Math.Max(first.LeftX, second.LeftX),
            bottom = Math.Max(first.BottomY, second.BottomY);
        int right = Math.Min(first.LeftX + first.Width, second.LeftX + second.Width);
        int top = Math.Min(first.BottomY + first.Height, second.BottomY + second.Height);
        return right <= left || top <= bottom
                   ? new Rectangle()
                   : new Rectangle(left, bottom, right - left, top - bottom);
    }
}

