public class Solution
{
    public ISet<string> GetPermutations(string text)
    {
        if (text.Length == 0)
            return new HashSet<string> { "" };
        var result = new HashSet<string>();
        foreach (string rest in GetPermutations(text[1..]))
            for (int i = 0; i <= rest.Length; i++)
                result.Add(rest.Insert(i, text[..1]));
        return result;
    }
}

