public class Solution
{
    private static void ReverseRange(char[] message, int left, int right)
    {
        while (left < right)
        {
            (message[left], message[right]) = (message[right], message[left]);
            left++;
            right--;
        }
    }
    public void ReverseWords(char[] message)
    {
        ReverseRange(message, 0, message.Length - 1);
        int start = 0;
        for (int end = 0; end <= message.Length; end++)
            if (end == message.Length || message[end] == ' ')
            {
                ReverseRange(message, start, end - 1);
                start = end + 1;
            }
    }
}

