class TempTracker {
  constructor() {
    this.count = 0;
    this.total = 0;
    this.minimum = null;
    this.maximum = null;
    this.counts = Array(111).fill(0);
    this.mode = null;
    this.modeCount = 0;
  }
  Insert(temperature) {
    this.count++;
    this.total += temperature;
    this.minimum = this.minimum === null ? temperature : Math.min(this.minimum, temperature);
    this.maximum = this.maximum === null ? temperature : Math.max(this.maximum, temperature);
    this.counts[temperature]++;
    if (this.counts[temperature] > this.modeCount) {
      this.mode = temperature;
      this.modeCount = this.counts[temperature];
    }
  }
  GetMin() {
    return this.minimum;
  }
  GetMax() {
    return this.maximum;
  }
  GetMean() {
    return this.count === 0 ? null : this.total / this.count;
  }
  GetMode() {
    return this.mode;
  }
}

