class TempTracker {
  array<int, 111> counts{};
  long long sum = 0;
  int count = 0, minimum = 0, maximum = 0, mode = 0;

 public:
  void Insert(int temperature) {
    if (count == 0)
      minimum = maximum = mode = temperature;
    minimum = min(minimum, temperature);
    maximum = max(maximum, temperature);
    sum += temperature;
    ++count;
    ++counts[temperature];
    if (counts[temperature] > counts[mode])
      mode = temperature;
  }
  optional<int> GetMin() {
    return count ? optional<int>(minimum) : nullopt;
  }
  optional<int> GetMax() {
    return count ? optional<int>(maximum) : nullopt;
  }
  optional<double> GetMean() {
    return count ? optional<double>(static_cast<double>(sum) / count) : nullopt;
  }
  optional<int> GetMode() {
    return count ? optional<int>(mode) : nullopt;
  }
};

