entries.solutionCode:
class Solution {
 public:
  long long MaxDuffelBagValue(vector<CakeType*>& types, int capacity) {
    for (auto cake : types)
      if (cake->Weight == 0 && cake->Value > 0)
        throw InfinityException();
    vector<long long> best(capacity + 1);
    for (int weight = 1; weight <= capacity; ++weight) {
      for (auto cake : types)
        if (cake->Weight > 0 && cake->Weight <= weight)
          best[weight] = max(best[weight], cake->Value + best[weight - cake->Weight]);
    }
    return best[capacity];
  }
};

