class Solution {
  SortScores(scores, highestPossibleScore) {
    const counts = Array(highestPossibleScore + 1).fill(0),
      sorted = [];
    for (const score of scores) counts[score]++;
    for (let score = highestPossibleScore; score >= 0; score--)
      for (let copy = 0; copy < counts[score]; copy++) sorted.push(score);
    return sorted;
  }
}

