class Solution {
 public:
  vector<int> SortScores(vector<int>& scores, int highestPossibleScore) {
    vector<int> counts(highestPossibleScore + 1);
    for (int score : scores)
      ++counts[score];
    vector<int> ordered;
    ordered.reserve(scores.size());
    for (int score = highestPossibleScore; score >= 0; --score)
      for (int i = 0; i < counts[score]; ++i)
        ordered.push_back(score);
    return ordered;
  }
};

